INSERT INTO public.fuel_meals
  (slug, name, protein_cut, spice_profile, format, active_cook_minutes, total_minutes, servings, protein_g_per_person, perishable_within_days, rotation_note, ingredients)
VALUES
  ('beef-barley-stew', 'Beef and barley stew, carrots and thyme', 'chuck', 'thyme-bay', 'braise', 25, 150, 8, 44, 4, 'STEW. 25 minutes of hands-on at the front, then it is the oven''s problem for two hours. Feeds 8 — plan it for a night you want tomorrow''s lunch too.', '[{"item":"beef chuck","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"pearl barley","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"carrot","qty_per_person":1.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"yellow onion","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"beef stock","qty_per_person":1.5,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"tomato paste","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true},{"item":"dried thyme","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('chicken-tortilla-soup', 'Chicken tortilla soup, lime and avocado', 'chicken_thigh', 'cumin-chili', 'soup', 20, 45, 6, 42, 3, 'SOUP. Thighs poach in the broth and shred straight into it, so no separate cook step. Avocado and tortilla strips go on at the table.', '[{"item":"chicken thigh, boneless skinless","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"fire-roasted diced tomatoes","qty_per_person":0.5,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"black beans","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"chicken stock","qty_per_person":1.5,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"avocado","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"lime","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"ground cumin","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"corn tortilla","qty_per_person":1,"unit":"each","store_section":"Pantry","inferred":true}]'::jsonb),
  ('white-chicken-chili', 'White chicken chili, green chile and lime', 'chicken_breast', 'green-chile-cumin', 'soup', 20, 45, 6, 45, 3, 'SOUP. Thickens on white beans rather than cream. Keeps four days and tastes better on day two.', '[{"item":"chicken breast","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"cannellini beans","qty_per_person":0.5,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"diced green chiles","qty_per_person":0.25,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"chicken stock","qty_per_person":1.5,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"yellow onion","qty_per_person":0.4,"unit":"each","store_section":"Produce","inferred":true},{"item":"lime","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"ground cumin","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('italian-wedding-soup', 'Italian wedding soup, turkey meatballs and greens', 'ground_turkey', 'garlic-herb-italian', 'soup', 25, 45, 6, 41, 3, 'SOUP. Meatballs are rolled small and poached in the broth — no browning step. Uses the same 93/7 as the other turkey nights.', '[{"item":"ground turkey 93/7","qty_per_person":6.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"escarole or spinach","qty_per_person":3,"unit":"oz","store_section":"Produce","inferred":true},{"item":"acini di pepe or orzo","qty_per_person":0.25,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"chicken stock","qty_per_person":1.75,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"parmesan","qty_per_person":0.5,"unit":"oz","store_section":"Dairy","inferred":true},{"item":"egg","qty_per_person":0.25,"unit":"each","store_section":"Dairy","inferred":true},{"item":"garlic","qty_per_person":1,"unit":"clove","store_section":"Produce","inferred":true}]'::jsonb),
  ('pork-green-chili', 'Pork green chili, tomatillo and potato', 'pork_shoulder', 'tomatillo-green-chile', 'braise', 25, 180, 8, 46, 4, 'STEW. Three hours, nearly all unattended. Freezes well — this is the one to make double of.', '[{"item":"pork shoulder","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"tomatillo","qty_per_person":3,"unit":"oz","store_section":"Produce","inferred":true},{"item":"poblano pepper","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"russet potato","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"chicken stock","qty_per_person":1,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"yellow onion","qty_per_person":0.4,"unit":"each","store_section":"Produce","inferred":true},{"item":"ground cumin","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"lime","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true}]'::jsonb),
  ('lentil-sausage-soup', 'Lentil soup with chicken sausage and kale', 'chicken_sausage', 'smoked-paprika', 'soup', 15, 40, 6, 40, 4, 'SOUP. Cheapest night in the book and still clears the protein floor. Lentils need no soaking.', '[{"item":"chicken sausage","qty_per_person":5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"brown lentils","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"kale","qty_per_person":2.5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"carrot","qty_per_person":1,"unit":"each","store_section":"Produce","inferred":true},{"item":"chicken stock","qty_per_person":1.5,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"smoked paprika","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"garlic","qty_per_person":1,"unit":"clove","store_section":"Produce","inferred":true}]'::jsonb),
  ('turkey-chili', 'Turkey chili, three beans and cocoa', 'ground_turkey', 'chili-cocoa', 'soup', 20, 50, 8, 43, 4, 'CHILI. The cocoa is a teaspoon and nobody tastes chocolate — it just makes it read as having simmered all day. Feeds 8.', '[{"item":"ground turkey 93/7","qty_per_person":6.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"kidney beans","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"black beans","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"crushed tomatoes","qty_per_person":0.75,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"yellow onion","qty_per_person":0.4,"unit":"each","store_section":"Produce","inferred":true},{"item":"chili powder","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"unsweetened cocoa powder","qty_per_person":0.25,"unit":"tsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('zuppa-toscana', 'Zuppa toscana — sausage, potato and kale', 'chicken_sausage', 'fennel-chili-flake', 'soup', 20, 40, 6, 41, 3, 'SOUP. Chicken sausage instead of pork keeps the fat sane without losing the fennel. Half-and-half at the end, off the heat.', '[{"item":"chicken sausage","qty_per_person":5.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"russet potato","qty_per_person":0.75,"unit":"each","store_section":"Produce","inferred":true},{"item":"kale","qty_per_person":2.5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"chicken stock","qty_per_person":1.5,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"half-and-half","qty_per_person":1,"unit":"tbsp","store_section":"Dairy","inferred":true},{"item":"garlic","qty_per_person":1,"unit":"clove","store_section":"Produce","inferred":true},{"item":"red pepper flakes","qty_per_person":0.25,"unit":"tsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('flank-chimichurri', 'Flank steak with chimichurri, blistered peppers', 'flank', 'chimichurri', 'grill-or-sear', 15, 25, 4, 46, 3, 'STEAK. Counts against the monthly steak cap alongside the ribeye. Chimichurri is a blender job and keeps a week.', '[{"item":"flank steak","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"mini sweet peppers","qty_per_person":4,"unit":"oz","store_section":"Produce","inferred":true},{"item":"flat-leaf parsley","qty_per_person":0.5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"garlic","qty_per_person":1,"unit":"clove","store_section":"Produce","inferred":true},{"item":"red wine vinegar","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"olive oil","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('smash-burgers', 'Smash burgers, griddled onion, side salad', 'ground_beef', 'salt-and-pepper', 'patty', 15, 20, 4, 44, 3, 'FAST. Twenty minutes start to plate. The kids will eat this one without negotiation.', '[{"item":"ground beef 90/10","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"brioche bun","qty_per_person":1,"unit":"each","store_section":"Pantry","inferred":true},{"item":"yellow onion","qty_per_person":0.3,"unit":"each","store_section":"Produce","inferred":true},{"item":"romaine","qty_per_person":2,"unit":"oz","store_section":"Produce","inferred":true},{"item":"cheddar","qty_per_person":0.75,"unit":"oz","store_section":"Dairy","inferred":true},{"item":"dill pickle","qty_per_person":1,"unit":"each","store_section":"Pantry","inferred":true}]'::jsonb),
  ('korean-beef-bowl', 'Korean beef bowl, cucumber and sesame rice', 'ground_beef', 'soy-sesame-gochujang', 'bowl', 15, 25, 4, 42, 3, 'BOWL. Gochujang is the only new jar and it lasts months in the fridge. Cucumber goes on raw for crunch.', '[{"item":"ground beef 90/10","qty_per_person":6.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"jasmine rice","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"english cucumber","qty_per_person":0.4,"unit":"each","store_section":"Produce","inferred":true},{"item":"gochujang","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"soy sauce","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true},{"item":"toasted sesame oil","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"scallion","qty_per_person":1,"unit":"each","store_section":"Produce","inferred":true}]'::jsonb),
  ('beef-and-broccoli', 'Beef and broccoli, garlic ginger sauce', 'flank', 'soy-ginger-garlic', 'stir-fry', 20, 25, 4, 44, 3, 'STIR-FRY. Slice the flank against the grain while the rice cooks. Shares its sauce base with the soy-ginger stir-fry already in rotation A.', '[{"item":"flank steak","qty_per_person":6.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"broccoli","qty_per_person":5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"jasmine rice","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"soy sauce","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true},{"item":"fresh ginger","qty_per_person":1,"unit":"tsp","store_section":"Produce","inferred":true},{"item":"garlic","qty_per_person":1,"unit":"clove","store_section":"Produce","inferred":true},{"item":"cornstarch","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('pork-tenderloin-apple', 'Pork tenderloin, apple and sage, roasted sprouts', 'pork_tenderloin', 'sage-apple', 'oven-roast', 15, 35, 4, 46, 3, 'ROAST. Tenderloin is the leanest cut in the book and cooks in 20 minutes. Pull it at 145F and let it rest.', '[{"item":"pork tenderloin","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"brussels sprouts","qty_per_person":5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"apple","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"dried sage","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"dijon mustard","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"olive oil","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('mustard-pork-chops', 'Pork chops, mustard pan sauce, green beans', 'pork_chop', 'dijon-thyme', 'pan-seared', 15, 25, 4, 45, 3, 'FAST. Sear, rest, build the sauce in the same pan. Bone-in chops are more forgiving than boneless.', '[{"item":"bone-in pork chop","qty_per_person":8,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"green beans","qty_per_person":5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"dijon mustard","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"chicken stock","qty_per_person":0.25,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"dried thyme","qty_per_person":0.25,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"butter","qty_per_person":0.5,"unit":"tbsp","store_section":"Dairy","inferred":true}]'::jsonb),
  ('carnitas-bowls', 'Carnitas bowls, pickled onion and cilantro', 'pork_shoulder', 'orange-cumin-oregano', 'braise', 20, 210, 8, 44, 4, 'BRAISE. Three and a half hours, twenty minutes of work. Crisp it under the broiler at the end — that step is the whole dish.', '[{"item":"pork shoulder","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"jasmine rice","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"red onion","qty_per_person":0.3,"unit":"each","store_section":"Produce","inferred":true},{"item":"orange","qty_per_person":0.25,"unit":"each","store_section":"Produce","inferred":true},{"item":"cilantro","qty_per_person":0.25,"unit":"oz","store_section":"Produce","inferred":true},{"item":"ground cumin","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"dried oregano","qty_per_person":0.25,"unit":"tsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('garlic-shrimp-skillet', 'Garlic shrimp, charred corn, lemon rice', 'shrimp', 'garlic-lemon-chili', 'skillet', 15, 25, 4, 41, 2, 'FAST. Shrimp cook in four minutes — have everything else done first. Frozen raw shrimp from the bag is the right buy here.', '[{"item":"raw shrimp, peeled","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"corn","qty_per_person":3,"unit":"oz","store_section":"Produce","inferred":true},{"item":"jasmine rice","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"garlic","qty_per_person":2,"unit":"clove","store_section":"Produce","inferred":true},{"item":"lemon","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"red pepper flakes","qty_per_person":0.25,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"butter","qty_per_person":0.5,"unit":"tbsp","store_section":"Dairy","inferred":true}]'::jsonb),
  ('shrimp-fajitas', 'Shrimp fajitas, peppers and onion', 'shrimp', 'fajita-chili-lime', 'sheet-pan', 20, 25, 4, 40, 2, 'SHEET-PAN. Everything on one tray. Shrimp go in for the last six minutes only, after the peppers have had a head start.', '[{"item":"raw shrimp, peeled","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"bell pepper","qty_per_person":1,"unit":"each","store_section":"Produce","inferred":true},{"item":"yellow onion","qty_per_person":0.4,"unit":"each","store_section":"Produce","inferred":true},{"item":"flour tortilla","qty_per_person":1.5,"unit":"each","store_section":"Pantry","inferred":true},{"item":"chili powder","qty_per_person":0.75,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"lime","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true}]'::jsonb),
  ('chicken-shawarma-bowl', 'Chicken shawarma bowl, cucumber salad, garlic sauce', 'chicken_thigh', 'shawarma', 'marinate-and-roast', 20, 40, 4, 45, 3, 'BOWL. Marinade is pantry spices and yogurt — build it in the morning and it is a 20-minute night.', '[{"item":"chicken thigh, boneless skinless","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"english cucumber","qty_per_person":0.4,"unit":"each","store_section":"Produce","inferred":true},{"item":"cherry tomato","qty_per_person":3,"unit":"oz","store_section":"Produce","inferred":true},{"item":"greek yogurt","qty_per_person":2,"unit":"oz","store_section":"Dairy","inferred":true},{"item":"jasmine rice","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"ground cumin","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"ground coriander","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"garlic","qty_per_person":1,"unit":"clove","store_section":"Produce","inferred":true}]'::jsonb),
  ('chicken-piccata', 'Chicken piccata, capers and lemon, asparagus', 'chicken_breast', 'lemon-caper', 'pan-seared', 20, 25, 4, 47, 3, 'FAST. Pound the breasts thin and they cook in six minutes. Capers are the only unusual jar and they keep forever.', '[{"item":"chicken breast","qty_per_person":7.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"asparagus","qty_per_person":5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"capers","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"lemon","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"chicken stock","qty_per_person":0.25,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"butter","qty_per_person":0.5,"unit":"tbsp","store_section":"Dairy","inferred":true},{"item":"all-purpose flour","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('arroz-con-pollo', 'Arroz con pollo, peas and peppers', 'chicken_thigh', 'sofrito-paprika', 'one-pot', 20, 45, 6, 43, 3, 'ONE-POT. Rice cooks in the same pan under the chicken. One pot to wash, which on a Wednesday is the point.', '[{"item":"chicken thigh, boneless skinless","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"jasmine rice","qty_per_person":0.4,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"bell pepper","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"frozen peas","qty_per_person":2,"unit":"oz","store_section":"Produce","inferred":true},{"item":"chicken stock","qty_per_person":0.75,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"smoked paprika","qty_per_person":0.5,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"yellow onion","qty_per_person":0.3,"unit":"each","store_section":"Produce","inferred":true}]'::jsonb),
  ('honey-soy-mahi', 'Honey-soy mahi, snap peas, rice', 'mahi', 'honey-soy', 'pan-seared', 15, 20, 4, 43, 2, 'FISH — fast. Twenty minutes and the glaze is three pantry items. Mahi holds together better than cod in a hot pan.', '[{"item":"mahi mahi","qty_per_person":7,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"sugar snap peas","qty_per_person":4,"unit":"oz","store_section":"Produce","inferred":true},{"item":"jasmine rice","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"soy sauce","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true},{"item":"honey","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"fresh ginger","qty_per_person":0.5,"unit":"tsp","store_section":"Produce","inferred":true}]'::jsonb),
  ('lemon-crumb-haddock', 'Lemon-crumb haddock, roasted carrots', 'haddock', 'lemon-herb-crumb', 'oven-roast', 15, 25, 4, 41, 2, 'FISH — oven. The crumb goes on dry and crisps without frying. A white-fish night that is not the cod tacos.', '[{"item":"haddock","qty_per_person":7.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"carrot","qty_per_person":1.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"panko breadcrumbs","qty_per_person":2,"unit":"tbsp","store_section":"Pantry","inferred":true},{"item":"lemon","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"dried parsley","qty_per_person":0.25,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"olive oil","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('sheet-pan-sausage-peppers', 'Sheet-pan chicken sausage, peppers and potatoes', 'chicken_sausage', 'italian-fennel', 'sheet-pan', 10, 35, 4, 40, 4, 'SHEET-PAN. Ten minutes of knife work and the oven does the rest. The lowest-effort night in the book.', '[{"item":"chicken sausage","qty_per_person":6,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"bell pepper","qty_per_person":1,"unit":"each","store_section":"Produce","inferred":true},{"item":"baby potatoes","qty_per_person":5,"unit":"oz","store_section":"Produce","inferred":true},{"item":"yellow onion","qty_per_person":0.4,"unit":"each","store_section":"Produce","inferred":true},{"item":"italian seasoning","qty_per_person":0.75,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"olive oil","qty_per_person":1,"unit":"tbsp","store_section":"Pantry","inferred":true}]'::jsonb),
  ('turkey-taco-skillet', 'Turkey taco skillet, black beans and lime slaw', 'ground_turkey', 'taco-chili-lime', 'skillet', 15, 25, 4, 42, 3, 'FAST. One skillet, 25 minutes, and the slaw is bagged cabbage with lime on it. Uses the 93/7 already on the list.', '[{"item":"ground turkey 93/7","qty_per_person":6.5,"unit":"oz","store_section":"Meat & Seafood","inferred":false},{"item":"black beans","qty_per_person":0.33,"unit":"cup dry","store_section":"Pantry","inferred":true},{"item":"shredded cabbage","qty_per_person":3,"unit":"oz","store_section":"Produce","inferred":true},{"item":"lime","qty_per_person":0.5,"unit":"each","store_section":"Produce","inferred":true},{"item":"chili powder","qty_per_person":1,"unit":"tsp","store_section":"Pantry","inferred":true},{"item":"corn tortilla","qty_per_person":2,"unit":"each","store_section":"Pantry","inferred":true}]'::jsonb)
